/// Icon size: 16px beside text, 20px on its own.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum IconSize {
    /// 16px.
    #[default]
    Small,
    /// 20px.
    Medium,
}

/// A Phosphor icon. Decorative: the words next to it carry the meaning.
#[component]
pub fn Icon(
    /// Which icon.
    name: IconName,
    /// 16px by default.
    #[prop(optional)]
    size: IconSize,
) -> impl IntoView {
    let class = match size {
        IconSize::Small => "ui-icon",
        IconSize::Medium => "ui-icon ui-icon--md",
    };
    view! {
        <svg class=class viewBox="0 0 256 256" aria-hidden="true" focusable="false">
            <path d=name.path()></path>
        </svg>
    }
}
